// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { AtSignIcon, CheckIcon, HeartIcon, ImageIcon, SearchIcon } from 'lucide-react'

import { Bar, BrowserChrome, DemoStage, DockHeader, type Build } from '@/app/demos/stage'

import {
  CAPTIONS,
  CHARS,
  DRAFT,
  FILLS,
  QUERY,
  RESULTS,
  SEARCH_URL,
  THREADS,
  TWEET_LIMIT,
  UI,
} from './script'

const build: Build = ({ tl, q, qa, step, final, move, click, type, count, wait, cursorOut }) => {
  const pop = (token: number) =>
    tl.fromTo(
      q(`token-${token}`),
      { opacity: 0, y: 4 },
      { opacity: 1, y: 0, duration: 0.3, ease: 'back.out(3)', immediateRender: false },
      '<',
    )

  step(0)
  FILLS.forEach((fill, index) => {
    move(`in-${fill.key}`, { at: index === 0 ? 0.3 : undefined, ax: 0.3 })
    click(`in-${fill.key}`)
    if (fill.key === 'media') {
      tl.to(
        q('media-box'),
        { backgroundColor: '#1d9bf0', borderColor: '#1d9bf0', duration: 0.15 },
        '<',
      )
      tl.fromTo(
        q('media-check'),
        { scale: 0 },
        { scale: 1, duration: 0.25, ease: 'back.out(3)', immediateRender: false },
        '<',
      )
    } else {
      tl.to(q(`ph-${fill.key}`), { opacity: 0, duration: 0.1 }, '<')
      type(`val-${fill.key}`, fill.value, { speed: 0.04 })
    }
    pop(index)
  })

  step(1, '+=0.4')
  move('open')
  click('open')
  tl.to(
    q('url-text'),
    { text: { value: SEARCH_URL, delimiter: '' }, duration: 0.5, ease: 'none' },
    '<',
  )
  tl.to(q('home'), { opacity: 0, duration: 0.25 }, '<')
  tl.fromTo(
    q('results'),
    { opacity: 0 },
    { opacity: 1, duration: 0.3, immediateRender: false },
    '<0.2',
  )
  tl.from(
    qa('result'),
    { opacity: 0, y: 14, duration: 0.4, stagger: 0.12, ease: 'power3.out', immediateRender: false },
    '<0.1',
  )

  step(2, '+=0.9')
  move('draft', { ax: 0.3, ay: 0.3 })
  click('draft')
  const start = tl.duration()
  const typing = 2.6
  type('draft-text', DRAFT, { at: start, speed: typing / DRAFT.length })
  count('chars', CHARS, { at: start, duration: typing, ease: 'none' })
  tl.set(q('threads'), { text: String(THREADS) }, start + (typing * TWEET_LIMIT) / CHARS)
  tl.fromTo(
    q('stats'),
    { color: '#1d9bf0' },
    { color: 'var(--demo-muted)', duration: 0.8, immediateRender: false },
    '<',
  )
  cursorOut(start + 0.4)
  final(start + typing + 0.2)
  wait(1.2)

  tl.set(qa('token'), { opacity: 0 }, 0)
  tl.set(q('results'), { opacity: 0 }, 0)
  tl.set(q('threads'), { text: '1' }, 0)
  tl.set(q('media-check'), { scale: 0 }, 0)
}

function Input({
  k,
  placeholder,
  className,
}: {
  k: string
  placeholder: string
  className?: string
}) {
  return (
    <span
      data-d={`in-${k}`}
      className={`relative flex h-[18px] items-center rounded border border-line-strong bg-black/20 px-1.5 text-[9px] ${className ?? ''}`}
    >
      <span data-d={`ph-${k}`} className="absolute left-1.5 text-muted">
        {placeholder}
      </span>
      <span data-d={`val-${k}`} className="truncate text-ink" />
    </span>
  )
}

function Panel() {
  return (
    <div className="flex h-full flex-col">
      <DockHeader />
      <div className="flex flex-col gap-2 p-2.5">
        <div className="rounded-xl border border-line bg-ink/[0.03] p-2">
          <p className="text-[10.5px] font-semibold text-ink">{UI.searchTitle}</p>
          <div className="mt-1 grid gap-1">
            <Input k="from" placeholder={UI.from} />
            <Input k="exact" placeholder={UI.exact} />
            <div className="grid grid-cols-2 gap-1">
              <Input k="minFaves" placeholder={UI.minFaves} />
              <Input k="minRetweets" placeholder={UI.minRetweets} />
            </div>
            <div className="grid grid-cols-2 gap-1">
              <Input k="since" placeholder={UI.since} />
              <Input k="until" placeholder={UI.until} />
            </div>
            <span
              data-d="in-media"
              className="flex w-fit items-center gap-1.5 text-[9px] text-ink-soft"
            >
              <span
                data-d="media-box"
                className="flex size-2.5 items-center justify-center rounded-sm border border-line-strong"
              >
                <CheckIcon data-d="media-check" className="size-2 text-white" strokeWidth={4} />
              </span>
              {UI.media}
            </span>
          </div>
          <p className="mt-1.5 flex min-h-[30px] flex-wrap content-start gap-x-1 rounded border border-line bg-black/20 px-1.5 py-1 font-mono text-[8.5px] leading-[12px] text-ink">
            {FILLS.map((fill, index) => (
              <span key={fill.token} data-d={`token token-${index}`} className="text-[#7dd3fc]">
                {fill.token}
              </span>
            ))}
          </p>
          <p className="mt-1 flex items-center gap-2 text-[9px]">
            <span className="text-ink-soft">{UI.copy}</span>
            <span data-d="open" className="text-[#1d9bf0] underline">
              {UI.open}
            </span>
          </p>
        </div>
        <div className="rounded-xl border border-line bg-ink/[0.03] p-2">
          <p className="text-[10.5px] font-semibold text-ink">{UI.composeTitle}</p>
          <div
            data-d="draft"
            className="mt-1 flex h-[34px] flex-col justify-end overflow-hidden rounded border border-line-strong bg-black/20 px-1.5 py-1 text-[8px] leading-[11px] text-ink-soft"
          >
            <span data-d="draft-text" />
          </div>
          <p data-d="stats" className="mt-1 text-[9px] text-muted">
            <span data-d="chars">0</span> characters · ~<span data-d="threads">1</span> tweet(s)
          </p>
        </div>
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label={`X Power Tools building the search ${QUERY}, opening it on X, then estimating a thread`}
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome url="https://x.com/home" panel={<Panel />} panelWidth={226}>
        <div className="relative h-full bg-black text-white">
          <div data-d="home" className="space-y-3 p-3">
            {[0, 1, 2].map((row) => (
              <div key={row} className="flex gap-2">
                <span className="size-6 shrink-0 rounded-full bg-ink/15" />
                <div className="flex-1 space-y-1.5">
                  <Bar w="40%" className="h-1.5 bg-ink/25" />
                  <Bar w="92%" className="h-1.5 bg-ink/12" />
                  <Bar w="70%" className="h-1.5 bg-ink/12" />
                </div>
              </div>
            ))}
          </div>
          <div data-d="results" className="absolute inset-0 p-2.5 opacity-0">
            <div className="flex items-center gap-1.5 rounded-full border border-ink/15 px-2 py-1">
              <SearchIcon className="size-3 shrink-0 text-white/60" />
              <span className="truncate text-[8.5px] text-white/90">{QUERY}</span>
            </div>
            <div className="mt-1.5 flex gap-3 border-b border-ink/10 text-[8.5px] text-white/50">
              <span className="border-b-2 border-[#1d9bf0] pb-1 font-semibold text-white">Top</span>
              <span>Latest</span>
              <span>Media</span>
            </div>
            <div className="mt-2 space-y-2">
              {RESULTS.map((result) => (
                <div key={result.text} data-d="result" className="flex gap-2">
                  <span className="flex size-6 shrink-0 items-center justify-center rounded-full bg-[#1d9bf0]">
                    <AtSignIcon className="size-3" />
                  </span>
                  <div className="min-w-0 flex-1">
                    <p className="text-[8.5px]">
                      <span className="font-semibold">Northwind</span>{' '}
                      <span className="text-white/45">@northwindhq</span>
                    </p>
                    <p className="text-[8.5px] leading-snug text-white/85">{result.text}</p>
                    <span
                      className="mt-1 flex h-9 items-center justify-center rounded-md"
                      style={{ background: `linear-gradient(135deg, ${result.tint}, #0f172a)` }}
                    >
                      <ImageIcon className="size-3.5 text-white/70" />
                    </span>
                    <span className="mt-0.5 flex items-center gap-1 text-[8px] text-white/50">
                      <HeartIcon className="size-2.5" /> {result.likes}
                    </span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      </BrowserChrome>
    </DemoStage>
  )
}
